-- Degree Programs - Lot 9: juries, graduation, transcripts and degrees. Run after 017.
do $$ begin create type public.academic_jury_type as enum ('SEMESTER','YEAR','GRADUATION','DEFENSE'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_jury_status as enum ('DRAFT','CONVENED','IN_SESSION','DECISIONS_RECORDED','CLOSED','CANCELLED'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_decision_status as enum ('PROPOSED','APPROVED','PUBLISHED','REVOKED'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_eligibility_status as enum ('PASSED','FAILED','OVERRIDDEN'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_transcript_status as enum ('GENERATED','PUBLISHED','REVOKED'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_degree_status as enum ('APPROVED','ISSUED','REVOKED','REPLACED'); exception when duplicate_object then null; end $$;
create sequence if not exists public.academic_jury_number_seq; create sequence if not exists public.academic_decision_number_seq; create sequence if not exists public.academic_transcript_number_seq; create sequence if not exists public.academic_degree_number_seq;
create table if not exists public.academic_juries(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),jury_number text not null unique,jury_type public.academic_jury_type not null,program_id uuid not null references public.academic_programs(id),academic_year_id uuid references public.academic_years(id),semester_id uuid references public.academic_semesters(id),meeting_date timestamptz not null,location_or_link text,chair_user_id uuid not null references public.profiles(id),quorum_required smallint not null default 2 check(quorum_required>0),status public.academic_jury_status not null default 'DRAFT',minutes_storage_path text,notes_fr text,notes_en text,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.academic_jury_members(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),jury_id uuid not null references public.academic_juries(id) on delete cascade,user_id uuid not null references public.profiles(id),member_role text not null check(member_role in('CHAIR','SECRETARY','MEMBER','RAPPORTEUR','EXTERNAL_EXAMINER')),present boolean not null default false,conflict_declared boolean not null default false,conflict_details text,signed_at timestamptz,created_at timestamptz not null default now(),unique(jury_id,user_id));
create table if not exists public.academic_graduation_eligibility_checks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),student_id uuid not null references public.academic_students(id),program_id uuid not null references public.academic_programs(id),status public.academic_eligibility_status not null,credits_earned numeric(8,2) not null,credits_required numeric(8,2) not null,checked_at timestamptz not null default now(),checked_by uuid not null references public.profiles(id),reason text not null,snapshot jsonb not null default '{}'::jsonb);
create table if not exists public.academic_graduation_check_items(id uuid primary key default gen_random_uuid(),check_id uuid not null references public.academic_graduation_eligibility_checks(id) on delete cascade,check_code text not null,label_fr text not null,label_en text not null,result text not null check(result in('PASS','FAIL','NOT_APPLICABLE','REQUIRES_REVIEW')),details_fr text,details_en text,evidence jsonb not null default '{}'::jsonb,unique(check_id,check_code));
create table if not exists public.academic_jury_decisions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),decision_number text not null unique,jury_id uuid not null references public.academic_juries(id),student_id uuid not null references public.academic_students(id),decision_type text not null check(decision_type in('SEMESTER','YEAR','PROGRESSION','GRADUATION','DEFENSE')),decision_value text not null,reason_fr text not null,reason_en text not null,effective_date date not null default current_date,eligibility_check_id uuid references public.academic_graduation_eligibility_checks(id),status public.academic_decision_status not null default 'PROPOSED',proposed_by uuid not null references public.profiles(id),proposed_at timestamptz not null default now(),validated_by uuid references public.profiles(id),validated_at timestamptz,unique(jury_id,student_id,decision_type));
create table if not exists public.academic_transcripts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),transcript_number text not null unique,verification_code text not null unique,student_id uuid not null references public.academic_students(id),program_id uuid not null references public.academic_programs(id),academic_year_id uuid references public.academic_years(id),semester_id uuid references public.academic_semesters(id),total_credits numeric(8,2) not null default 0,weighted_average numeric(7,2),status public.academic_transcript_status not null default 'GENERATED',storage_path text,generated_by uuid not null references public.profiles(id),generated_at timestamptz not null default now(),published_by uuid references public.profiles(id),published_at timestamptz);
create unique index if not exists academic_transcript_scope_uidx on public.academic_transcripts(student_id,coalesce(academic_year_id,'00000000-0000-0000-0000-000000000000'::uuid),coalesce(semester_id,'00000000-0000-0000-0000-000000000000'::uuid)) where status<>'REVOKED';
create table if not exists public.academic_transcript_lines(id uuid primary key default gen_random_uuid(),transcript_id uuid not null references public.academic_transcripts(id) on delete cascade,course_id uuid references public.academic_courses(id),course_code text not null,course_name_fr text not null,course_name_en text not null,credits numeric(6,2) not null,coefficient numeric(6,2) not null,final_grade numeric(7,2),result text not null,display_order integer not null default 0);
create table if not exists public.academic_degree_awards(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),degree_number text not null unique,verification_code text not null unique,student_id uuid not null references public.academic_students(id),program_id uuid not null references public.academic_programs(id),jury_decision_id uuid not null unique references public.academic_jury_decisions(id),degree_title_fr text not null,degree_title_en text not null,award_date date not null default current_date,status public.academic_degree_status not null default 'APPROVED',storage_path text,issued_by uuid references public.profiles(id),issued_at timestamptz,revoked_at timestamptz,revocation_reason text,created_at timestamptz not null default now());
create unique index if not exists academic_active_degree_uidx on public.academic_degree_awards(student_id,program_id) where status in('APPROVED','ISSUED');
create table if not exists public.academic_documents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),student_id uuid not null references public.academic_students(id),document_type text not null,source_table text not null,source_id uuid not null,document_number text not null,verification_code text not null unique,title_fr text not null,title_en text not null,storage_bucket text not null default 'academic-official-documents',storage_path text not null,mime_type text not null default 'application/pdf',version integer not null default 1,active boolean not null default true,issued_by uuid not null references public.profiles(id),issued_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb,unique(source_table,source_id,version));
create table if not exists public.academic_jury_history(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),jury_id uuid references public.academic_juries(id) on delete cascade,entity_type text not null,entity_id uuid not null,action text not null,old_status text,new_status text,reason text not null,changed_by uuid not null references public.profiles(id),changed_at timestamptz not null default now(),payload jsonb not null default '{}'::jsonb);
create or replace function public.academic_set_lot9_numbers() returns trigger language plpgsql set search_path=public as $$ begin
 if tg_table_name='academic_juries' and new.jury_number is null then new.jury_number='JRY-'||lpad(nextval('academic_jury_number_seq')::text,7,'0'); end if;
 if tg_table_name='academic_jury_decisions' and new.decision_number is null then new.decision_number='DEC-'||lpad(nextval('academic_decision_number_seq')::text,7,'0'); end if;
 if tg_table_name='academic_transcripts' then if new.transcript_number is null then new.transcript_number='TRN-'||lpad(nextval('academic_transcript_number_seq')::text,7,'0');end if;if new.verification_code is null then new.verification_code=upper(encode(gen_random_bytes(8),'hex'));end if;end if;
 if tg_table_name='academic_degree_awards' then if new.degree_number is null then new.degree_number='DEG-'||lpad(nextval('academic_degree_number_seq')::text,7,'0');end if;if new.verification_code is null then new.verification_code=upper(encode(gen_random_bytes(8),'hex'));end if;end if;return new;end $$;
do $$ declare t text;begin foreach t in array array['academic_juries','academic_jury_decisions','academic_transcripts','academic_degree_awards']loop execute format('drop trigger if exists %I_numbers on public.%I',t,t);execute format('create trigger %I_numbers before insert on public.%I for each row execute function public.academic_set_lot9_numbers()',t,t);end loop;end $$;
create or replace function public.academic_evaluate_graduation_eligibility(p_student uuid,p_program uuid,p_reason text) returns public.academic_graduation_eligibility_checks language plpgsql security definer set search_path=public as $$ declare s public.academic_students;p public.academic_programs;r public.academic_graduation_eligibility_checks;e numeric:=0;m boolean;sem boolean;i boolean;t boolean;f boolean;begin
 select * into s from public.academic_students where id=p_student and current_program_id=p_program;select * into p from public.academic_programs where id=p_program;if s.id is null or not public.academic_has_program_scope(s.organization_id,p_program,'graduation.check')then raise exception 'Graduation permission required or student mismatch';end if;
 select coalesce(sum(credits_earned),0)into e from public.academic_credit_ledger where student_id=s.id and level='COURSE';
 select not exists(select 1 from public.academic_courses c join public.academic_teaching_units u on u.id=c.teaching_unit_id join public.academic_program_versions v on v.id=u.program_version_id where v.program_id=p.id and v.status='APPROVED' and c.status='ACTIVE' and u.is_mandatory and not exists(select 1 from public.academic_course_results cr where cr.student_id=s.id and cr.course_id=c.id and cr.workflow_status='VALIDATED'))into m;
 select count(*)>=p.duration_semesters into sem from public.academic_semester_results where student_id=s.id and workflow_status='VALIDATED';
 select case when exists(select 1 from public.academic_teaching_units u join public.academic_program_versions v on v.id=u.program_version_id where v.program_id=p.id and v.status='APPROVED'and u.unit_type='INTERNSHIP')then exists(select 1 from public.academic_internships where student_id=s.id and status='VALIDATED')else true end into i;
 select case when exists(select 1 from public.academic_teaching_units u join public.academic_program_versions v on v.id=u.program_version_id where v.program_id=p.id and v.status='APPROVED'and u.unit_type='THESIS')then exists(select 1 from public.academic_theses th join public.academic_defenses d on d.thesis_id=th.id where th.student_id=s.id and th.status in('DEFENDED','VALIDATED')and d.decision='PASSED')else true end into t;
 select exists(select 1 from public.academic_administrative_registrations where student_id=s.id and status='VALIDATED')and not exists(select 1 from public.academic_administrative_registrations where student_id=s.id and financial_status not in('PAID','WAIVED'))into f;
 insert into public.academic_graduation_eligibility_checks(organization_id,student_id,program_id,status,credits_earned,credits_required,checked_by,reason)values(s.organization_id,s.id,p.id,case when e>=p.total_credits and m and sem and i and t and f then'PASSED'else'FAILED'end,e,p.total_credits,auth.uid(),p_reason)returning * into r;
 insert into public.academic_graduation_check_items(check_id,check_code,label_fr,label_en,result,details_fr,details_en)values(r.id,'CREDITS','Credits requis','Required credits',case when e>=p.total_credits then'PASS'else'FAIL'end,e||' / '||p.total_credits,e||' / '||p.total_credits),(r.id,'MANDATORY','Cours obligatoires','Mandatory courses',case when m then'PASS'else'FAIL'end,null,null),(r.id,'SEMESTERS','Semestres valides','Validated semesters',case when sem then'PASS'else'FAIL'end,null,null),(r.id,'INTERNSHIP','Stage valide','Validated internship',case when i then'PASS'else'FAIL'end,null,null),(r.id,'THESIS','Memoire et soutenance','Thesis and defense',case when t then'PASS'else'FAIL'end,null,null),(r.id,'CLEARANCE','Situation administrative et financiere','Administrative and financial clearance',case when f then'PASS'else'FAIL'end,null,null);return r;end $$;
create or replace function public.academic_transition_jury(p_id uuid,p_status public.academic_jury_status,p_reason text)returns public.academic_juries language plpgsql security definer set search_path=public as $$ declare j public.academic_juries;o text;n int;begin select * into j from public.academic_juries where id=p_id for update;if not public.academic_has_program_scope(j.organization_id,j.program_id,'jury.manage')then raise exception 'Jury permission required';end if;o=j.status::text;if(o,p_status::text)not in(('DRAFT','CONVENED'),('CONVENED','IN_SESSION'),('IN_SESSION','DECISIONS_RECORDED'),('DECISIONS_RECORDED','CLOSED'),('DRAFT','CANCELLED'),('CONVENED','CANCELLED'))then raise exception 'Invalid transition';end if;if p_status='IN_SESSION'then select count(*)into n from public.academic_jury_members where jury_id=j.id and present and signed_at is not null and not conflict_declared;if n<j.quorum_required then raise exception 'Quorum incomplete';end if;end if;if p_status='CLOSED'and(j.minutes_storage_path is null or not exists(select 1 from public.academic_jury_decisions where jury_id=j.id and status='APPROVED'))then raise exception 'Approved decisions and minutes required';end if;update public.academic_juries set status=p_status,updated_at=now()where id=j.id returning * into j;insert into public.academic_jury_history(organization_id,jury_id,entity_type,entity_id,action,old_status,new_status,reason,changed_by)values(j.organization_id,j.id,'JURY',j.id,'STATUS_CHANGED',o,p_status::text,p_reason,auth.uid());return j;end $$;
create or replace function public.academic_record_jury_minutes(p_id uuid,p_path text,p_reason text)returns public.academic_juries language plpgsql security definer set search_path=public as $$declare j public.academic_juries;begin select * into j from public.academic_juries where id=p_id for update;if not public.academic_has_program_scope(j.organization_id,j.program_id,'jury.manage')or nullif(trim(p_path),'')is null then raise exception 'Jury permission and minutes path required';end if;update public.academic_juries set minutes_storage_path=p_path,updated_at=now()where id=j.id returning * into j;insert into public.academic_jury_history(organization_id,jury_id,entity_type,entity_id,action,reason,changed_by,payload)values(j.organization_id,j.id,'JURY',j.id,'MINUTES_RECORDED',p_reason,auth.uid(),jsonb_build_object('storage_path',p_path));return j;end$$;create or replace function public.academic_sign_jury_membership(p_id uuid,p_present boolean,p_conflict boolean,p_details text)returns public.academic_jury_members language plpgsql security definer set search_path=public as $$declare r public.academic_jury_members;begin select * into r from public.academic_jury_members where id=p_id;if r.user_id<>auth.uid()then raise exception 'Only designated member may sign';end if;if p_conflict and nullif(trim(p_details),'')is null then raise exception 'Conflict details required';end if;update public.academic_jury_members set present=p_present,conflict_declared=p_conflict,conflict_details=p_details,signed_at=now()where id=r.id returning * into r;return r;end$$;
create or replace function public.academic_approve_jury_decision(p_id uuid,p_reason text)returns public.academic_jury_decisions language plpgsql security definer set search_path=public as $$declare d public.academic_jury_decisions;j public.academic_juries;c public.academic_graduation_eligibility_checks;p public.academic_programs;begin select * into d from public.academic_jury_decisions where id=p_id for update;select * into j from public.academic_juries where id=d.jury_id;if not(j.chair_user_id=auth.uid()or public.academic_has_program_scope(j.organization_id,j.program_id,'jury.decide'))or j.status not in('IN_SESSION','DECISIONS_RECORDED')then raise exception 'Decision approval not allowed';end if;if d.decision_type='GRADUATION'and d.decision_value='GRADUATE'then select * into c from public.academic_graduation_eligibility_checks where id=d.eligibility_check_id;if c.status<>'PASSED'then raise exception 'Eligibility failed';end if;select * into p from public.academic_programs where id=j.program_id;insert into public.academic_degree_awards(organization_id,student_id,program_id,jury_decision_id,degree_title_fr,degree_title_en)values(j.organization_id,d.student_id,j.program_id,d.id,p.name_fr,p.name_en);update public.academic_students set academic_status='GRADUATED',updated_at=now()where id=d.student_id;end if;update public.academic_jury_decisions set status='APPROVED',validated_by=auth.uid(),validated_at=now()where id=d.id returning * into d;insert into public.academic_jury_history(organization_id,jury_id,entity_type,entity_id,action,old_status,new_status,reason,changed_by)values(j.organization_id,j.id,'DECISION',d.id,'HUMAN_APPROVAL','PROPOSED','APPROVED',p_reason,auth.uid());return d;end$$;
create or replace function public.academic_generate_transcript(p_student uuid,p_year uuid,p_semester uuid,p_reason text)returns public.academic_transcripts language plpgsql security definer set search_path=public as $$declare s public.academic_students;r public.academic_transcripts;begin select * into s from public.academic_students where id=p_student;if not public.academic_has_program_scope(s.organization_id,s.current_program_id,'transcript.generate')then raise exception 'Transcript permission required';end if;insert into public.academic_transcripts(organization_id,student_id,program_id,academic_year_id,semester_id,total_credits,weighted_average,generated_by)select s.organization_id,s.id,s.current_program_id,p_year,p_semester,coalesce(sum(cr.credits_earned),0),case when sum(c.coefficient)>0 then round(sum(cr.final_score*c.coefficient)/sum(c.coefficient),2)end,auth.uid()from public.academic_course_results cr join public.academic_courses c on c.id=cr.course_id join public.academic_semesters sm on sm.id=cr.semester_id where cr.student_id=s.id and cr.workflow_status='VALIDATED'and(p_year is null or sm.academic_year_id=p_year)and(p_semester is null or sm.id=p_semester)returning * into r;insert into public.academic_transcript_lines(transcript_id,course_id,course_code,course_name_fr,course_name_en,credits,coefficient,final_grade,result,display_order)select r.id,c.id,c.code::text,c.name_fr,c.name_en,c.credits,c.coefficient,cr.final_score,cr.result_status::text,row_number()over(order by c.code)from public.academic_course_results cr join public.academic_courses c on c.id=cr.course_id join public.academic_semesters sm on sm.id=cr.semester_id where cr.student_id=s.id and cr.workflow_status='VALIDATED'and(p_year is null or sm.academic_year_id=p_year)and(p_semester is null or sm.id=p_semester);return r;end$$;
create or replace function public.academic_publish_transcript(p_id uuid,p_path text,p_reason text)returns public.academic_transcripts language plpgsql security definer set search_path=public as $$declare r public.academic_transcripts;begin select * into r from public.academic_transcripts where id=p_id for update;if not public.academic_has_program_scope(r.organization_id,r.program_id,'transcript.generate')or r.status<>'GENERATED'or nullif(trim(p_path),'')is null then raise exception 'Publication requirements not met';end if;update public.academic_transcripts set status='PUBLISHED',storage_path=p_path,published_by=auth.uid(),published_at=now()where id=r.id returning * into r;insert into public.academic_documents(organization_id,student_id,document_type,source_table,source_id,document_number,verification_code,title_fr,title_en,storage_path,issued_by)values(r.organization_id,r.student_id,'TRANSCRIPT','academic_transcripts',r.id,r.transcript_number,r.verification_code,'Releve officiel','Official transcript',p_path,auth.uid());return r;end$$;
create or replace function public.academic_issue_degree(p_id uuid,p_path text,p_reason text)returns public.academic_degree_awards language plpgsql security definer set search_path=public as $$declare r public.academic_degree_awards;begin select * into r from public.academic_degree_awards where id=p_id for update;if not public.academic_has_program_scope(r.organization_id,r.program_id,'degree.issue')or r.status<>'APPROVED'or nullif(trim(p_path),'')is null then raise exception 'Degree issue requirements not met';end if;update public.academic_degree_awards set status='ISSUED',storage_path=p_path,issued_by=auth.uid(),issued_at=now()where id=r.id returning * into r;insert into public.academic_documents(organization_id,student_id,document_type,source_table,source_id,document_number,verification_code,title_fr,title_en,storage_path,issued_by)values(r.organization_id,r.student_id,'DEGREE','academic_degree_awards',r.id,r.degree_number,r.verification_code,r.degree_title_fr,r.degree_title_en,p_path,auth.uid());return r;end$$;
create or replace function public.academic_verify_official_document(p_code text)returns table(document_type text,document_number text,issued_on date,status text)language sql stable security definer set search_path=public as $$select 'DEGREE',degree_number,award_date,status::text from public.academic_degree_awards where verification_code=upper(trim(p_code))and status='ISSUED' union all select 'TRANSCRIPT',transcript_number,published_at::date,status::text from public.academic_transcripts where verification_code=upper(trim(p_code))and status='PUBLISHED'$$;insert into public.academic_role_permissions(role,permission_code,description_fr,description_en)values('JURY_MEMBER','jury.read','Consulter ses jurys','Read assigned juries'),('JURY_MEMBER','jury.sign','Signer sa presence','Sign attendance'),('JURY_CHAIR','jury.read','Consulter les jurys','Read juries'),('JURY_CHAIR','jury.manage','Gerer les jurys','Manage juries'),('JURY_CHAIR','jury.decide','Valider les decisions','Approve decisions'),('PROGRAM_COORDINATOR','jury.read','Consulter les jurys','Read juries'),('PROGRAM_COORDINATOR','jury.manage','Gerer les jurys','Manage juries'),('PROGRAM_COORDINATOR','graduation.check','Controler la diplomation','Check graduation'),('ACADEMIC_SECRETARY','jury.read','Consulter les jurys','Read juries'),('ACADEMIC_SECRETARY','transcript.generate','Generer les releves','Generate transcripts'),('ACADEMIC_ADMIN','jury.read','Consulter les jurys','Read juries'),('ACADEMIC_ADMIN','jury.manage','Gerer les jurys','Manage juries'),('ACADEMIC_ADMIN','jury.decide','Valider les decisions','Approve decisions'),('ACADEMIC_ADMIN','graduation.check','Controler la diplomation','Check graduation'),('ACADEMIC_ADMIN','transcript.generate','Generer les releves','Generate transcripts'),('ACADEMIC_ADMIN','degree.issue','Delivrer les diplomes','Issue degrees'),('SUPER_ADMIN','jury.read','Consulter les jurys','Read juries'),('SUPER_ADMIN','jury.manage','Gerer les jurys','Manage juries'),('SUPER_ADMIN','jury.decide','Valider les decisions','Approve decisions'),('SUPER_ADMIN','graduation.check','Controler la diplomation','Check graduation'),('SUPER_ADMIN','transcript.generate','Generer les releves','Generate transcripts'),('SUPER_ADMIN','degree.issue','Delivrer les diplomes','Issue degrees'),('STUDENT','official_documents.self.read','Consulter ses documents officiels','Read own official documents')on conflict(role,permission_code)do update set description_fr=excluded.description_fr,description_en=excluded.description_en;
do $$declare t text;begin foreach t in array array['academic_juries','academic_jury_members','academic_graduation_eligibility_checks','academic_graduation_check_items','academic_jury_decisions','academic_transcripts','academic_transcript_lines','academic_degree_awards','academic_documents','academic_jury_history']loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
drop policy if exists "juries read" on public.academic_juries;create policy "juries read" on public.academic_juries for select to authenticated using(public.academic_has_program_scope(organization_id,program_id,'jury.read')or chair_user_id=auth.uid());
drop policy if exists "juries create" on public.academic_juries;create policy "juries create" on public.academic_juries for insert to authenticated with check(created_by=auth.uid()and public.academic_has_program_scope(organization_id,program_id,'jury.manage'));
drop policy if exists "jury members read" on public.academic_jury_members;create policy "jury members read" on public.academic_jury_members for select to authenticated using(user_id=auth.uid()or exists(select 1 from public.academic_juries j where j.id=jury_id and public.academic_has_program_scope(j.organization_id,j.program_id,'jury.read')));
drop policy if exists "jury members create" on public.academic_jury_members;create policy "jury members create" on public.academic_jury_members for insert to authenticated with check(exists(select 1 from public.academic_juries j where j.id=jury_id and public.academic_has_program_scope(j.organization_id,j.program_id,'jury.manage')));
drop policy if exists "eligibility read" on public.academic_graduation_eligibility_checks;create policy "eligibility read" on public.academic_graduation_eligibility_checks for select to authenticated using(exists(select 1 from public.academic_students s where s.id=student_id and(s.user_id=auth.uid()or public.academic_has_program_scope(organization_id,program_id,'graduation.check'))));
drop policy if exists "eligibility items read" on public.academic_graduation_check_items;create policy "eligibility items read" on public.academic_graduation_check_items for select to authenticated using(exists(select 1 from public.academic_graduation_eligibility_checks c join public.academic_students s on s.id=c.student_id where c.id=check_id and(s.user_id=auth.uid()or public.academic_has_program_scope(c.organization_id,c.program_id,'graduation.check'))));
drop policy if exists "decisions read" on public.academic_jury_decisions;create policy "decisions read" on public.academic_jury_decisions for select to authenticated using(exists(select 1 from public.academic_students s where s.id=student_id and s.user_id=auth.uid())or exists(select 1 from public.academic_juries j where j.id=jury_id and(public.academic_has_program_scope(j.organization_id,j.program_id,'jury.read')or j.chair_user_id=auth.uid())));
drop policy if exists "decisions create" on public.academic_jury_decisions;create policy "decisions create" on public.academic_jury_decisions for insert to authenticated with check(proposed_by=auth.uid()and exists(select 1 from public.academic_juries j where j.id=jury_id and public.academic_has_program_scope(j.organization_id,j.program_id,'jury.manage')));
drop policy if exists "transcripts read" on public.academic_transcripts;create policy "transcripts read" on public.academic_transcripts for select to authenticated using(exists(select 1 from public.academic_students s where s.id=student_id and(s.user_id=auth.uid()or public.academic_has_program_scope(organization_id,program_id,'transcript.generate'))));
drop policy if exists "transcript lines read" on public.academic_transcript_lines;create policy "transcript lines read" on public.academic_transcript_lines for select to authenticated using(exists(select 1 from public.academic_transcripts t join public.academic_students s on s.id=t.student_id where t.id=transcript_id and(s.user_id=auth.uid()or public.academic_has_program_scope(t.organization_id,t.program_id,'transcript.generate'))));
drop policy if exists "degrees read" on public.academic_degree_awards;create policy "degrees read" on public.academic_degree_awards for select to authenticated using(exists(select 1 from public.academic_students s where s.id=student_id and(s.user_id=auth.uid()or public.academic_has_program_scope(organization_id,program_id,'degree.issue'))));
drop policy if exists "official docs read" on public.academic_documents;create policy "official docs read" on public.academic_documents for select to authenticated using(exists(select 1 from public.academic_students s where s.id=student_id and(s.user_id=auth.uid()or public.academic_has_program_scope(organization_id,s.current_program_id,'transcript.generate')or public.academic_has_program_scope(organization_id,s.current_program_id,'degree.issue'))));
drop policy if exists "jury history read" on public.academic_jury_history;create policy "jury history read" on public.academic_jury_history for select to authenticated using(exists(select 1 from public.academic_juries j where j.id=jury_id and(public.academic_has_program_scope(j.organization_id,j.program_id,'jury.read')or j.chair_user_id=auth.uid())));
